"use client";

import * as React from "react";
import type { TimelineAction, TimelineRow } from "@xzdarcy/timeline-engine";
import "@xzdarcy/react-timeline-editor/dist/react-timeline-editor.css";
import { cn } from "@/lib/utils";
import type { Clock } from "./clock";
import { Overlay, RULER_HEIGHT, TRACKS_TOP, type OverlayHandle } from "./overlay";
import { rulerLabel, snapTo, timecode } from "./ruler";
import { TrackHeaders, type TrackHeader, type TrackHeaderLabels, type TrackState } from "./track-headers";
import type { MediaTimelineController } from "./use-media-timeline";
import { VisibleTimeline } from "./window";

// Timeline de mídia (som, vídeo, legenda, nota) no nível de uma ferramenta de edição: régua que
// vira quadros de perto, agulha com scrub e ímã, seleção por área, navalha, HUD do arrasto,
// cabeçalhos de faixa (renomear, grupos, esconder, calar, solo, travar), zoom em gesto e só os
// clipes à vista no DOM. Não sabe de onde vêm os dados nem de API: faixas e clipes entram por
// props, o desenho de cada clipe é de quem usa (`renderClip`) e toda mudança sai por callback.
// Arrastar e aparar são da lib `@xzdarcy/react-timeline-editor`; o resto é camada por cima.

export interface MediaClip {
  id: string;
  start: number;
  end: number;
  /** Tipo livre (som, vídeo, nota): vai para o `renderClip` e para a classe da lib. */
  kind?: string;
  /** Nome para a dica do clipe estreito (sem nome, sem dica). */
  name?: string;
  movable?: boolean;
  resizable?: boolean;
  /** Selecionado (ou passe `selected` na timeline: trocar a seleção por lá não redesenha clipe). */
  selected?: boolean;
  /** A seleção por área e a navalha pegam este clipe (padrão: sim). */
  selectable?: boolean;
  /** Limites de arrasto (s). */
  min?: number;
  max?: number;
}

export interface MediaTrack extends Omit<TrackHeader, "height"> {
  height?: number;
  /** Os clipes. Mantenha o mesmo array enquanto nada mudar: a timeline só redesenha a faixa
   *  cujo array mudou. */
  clips: MediaClip[];
  /** Travada: não arrasta, não apara, a área e a navalha passam por cima. */
  locked?: boolean;
}

export interface ClipChange { clip: MediaClip; track: string; start: number; end: number }

export interface MediaTimelineProps {
  /** O estado de vista, de `useMediaTimeline`. */
  controller: MediaTimelineController;
  tracks: MediaTrack[];
  clock: Clock;
  /** Os clipes selecionados (ids). Marca no DOM (`.mt-clip[data-selected]`), sem redesenhar os
   *  clipes: com 300 clipes, cada troca de seleção pelos dados redesenhava todos, duas vezes. */
  selected?: ReadonlySet<string>;
  /** Mantenha a mesma função enquanto o desenho não muda (`useCallback`): uma função nova
   *  redesenha todos os clipes. */
  renderClip: (clip: MediaClip, track: string, info: { px: number }) => React.ReactNode;
  /** Altura padrão de uma faixa (px). */
  trackHeight?: number;
  tool?: "select" | "razor";
  /** Ímã: a agulha, a navalha e o arrasto grudam nos pontos (começos e fins, marcas). */
  snap?: boolean;
  snapPoints?: number[];
  /** Distância do ímã (px). */
  snapPx?: number;
  formatTime?: (t: number) => string;
  /** Estado dos botões de cada faixa (solo, calar, travar). */
  trackState?: (id: string) => TrackState;
  selectedTracks?: Set<string>;
  editingTrack?: string | null;
  headerLabels?: Partial<TrackHeaderLabels>;
  onTrackEdit?: (id: string | null) => void;
  onTrackRename?: (id: string, name: string) => void;
  onTrackSelect?: (id: string, additive: boolean) => void;
  onTrackLock?: (id: string) => void;
  onTrackMute?: (id: string) => void;
  onTrackSolo?: (id: string) => void;
  onTrackCollapse?: (id: string) => void;
  onTrackHide?: (id: string) => void;
  onMove?: (c: ClipChange) => void;
  onResize?: (c: ClipChange & { edge: "left" | "right" }) => void;
  onClipClick?: (clip: MediaClip, track: string, e: React.MouseEvent) => void;
  /** Clique no vazio de uma faixa (não vem logo depois de uma seleção por área). */
  onEmptyClick?: (e: React.MouseEvent) => void;
  /** Ao soltar a seleção por área: os ids pegos e se Shift/Ctrl somava. */
  onAreaSelect?: (ids: Set<string>, info: { additive: boolean }) => void;
  /** O que a área marca enquanto arrasta, dado o que ela pega (ex.: o bloco inteiro). */
  expandArea?: (ids: Set<string>) => Set<string>;
  /** Navalha: corte no tempo `t` (já no quadro e no ímã). */
  onCut?: (clip: MediaClip, track: string, t: number) => void;
  onScrubStart?: () => void;
  onScrub?: (t: number) => void;
  onScrubEnd?: (t: number) => void;
  onScroll?: (p: { left: number; top: number }) => void;
  /** Frase nas faixas vazias. */
  emptyHints?: { track: string; text: string }[];
  /** Atalhos próprios: = e − (zoom), Shift+Z (caber), V e C (ferramenta). Desligue se a tela já
   *  tem um teclado. */
  keyboard?: boolean;
  onToolChange?: (tool: "select" | "razor") => void;
  /** Envolve os cabeçalhos e a área (menu de contexto, por exemplo). */
  wrapHeaders?: (node: React.ReactElement) => React.ReactNode;
  wrapArea?: (node: React.ReactElement) => React.ReactNode;
  className?: string;
  headersClassName?: string;
  areaClassName?: string;
}

const STATE_OFF: TrackState = { locked: false, muted: false, solo: false };
const nada = () => {};

export function MediaTimeline(props: MediaTimelineProps) {
  const {
    controller: tl, tracks, clock, selected, renderClip, trackHeight = 34, tool = "select", snap = true, snapPoints = [], snapPx = 8,
    formatTime: fmt, trackState = () => STATE_OFF, selectedTracks, editingTrack = null, headerLabels,
    onMove, onResize, onClipClick, onEmptyClick, onAreaSelect, expandArea, onCut, onScrubStart, onScrub, onScrubEnd, onScroll,
    emptyHints, keyboard = true, onToolChange, wrapHeaders, wrapArea, className, headersClassName, areaClassName,
  } = props;
  const { startLeft, fps, pxPerSecond, ruler, width, duration } = tl;
  const formatTime = React.useMemo(() => fmt ?? ((t: number) => timecode(t, fps)), [fmt, fps]);
  const overlay = React.useRef<OverlayHandle>(null);
  const headers = React.useRef<HTMLDivElement>(null);
  const marqueeAt = React.useRef(0);
  // O que a seleção por área marca agora: o clipe que entra na janela no meio do gesto já nasce marcado.
  const inMarquee = React.useRef<Set<string>>(new Set());
  const areaActive = React.useRef(false);

  // ── Faixas e clipes → linhas da lib, com cache por array de clipes ──────────
  // A lib copia os dados para um estado e redesenha tudo quando o array muda; com o cache, um
  // render de quem usa que não mexeu em clipe nenhum não chega à lib.
  const cache = React.useRef(new WeakMap<MediaClip[], { row: TimelineRow; h: number; locked: boolean }>());
  const prevRows = React.useRef<TimelineRow[]>([]);
  const rows = React.useMemo(() => {
    const out = tracks.map((t) => {
      const h = t.height ?? trackHeight, locked = !!t.locked;
      const c = cache.current.get(t.clips);
      if (c && c.row.id === t.id && c.h === h && c.locked === locked) return c.row;
      const row: TimelineRow = {
        id: t.id, rowHeight: h,
        actions: t.clips.map((k) => ({
          id: k.id, start: k.start, end: k.end, effectId: k.kind ?? "clip",
          movable: !locked && k.movable !== false, flexible: !locked && k.resizable !== false,
          ...(k.min !== undefined ? { minStart: k.min } : {}), ...(k.max !== undefined ? { maxEnd: k.max } : {}),
        })),
      };
      cache.current.set(t.clips, { row, h, locked });
      return row;
    });
    const same = out.length === prevRows.current.length && out.every((r, i) => r === prevRows.current[i]);
    return same ? prevRows.current : (prevRows.current = out);
  }, [tracks, trackHeight]);
  // Pelas linhas, não pelas faixas: quem usa costuma montar as faixas a cada render, e um índice
  // novo redesenharia todos os clipes. As linhas só mudam quando um array de clipes, a altura ou
  // a trava mudam (o que o índice guarda da faixa: id e trava).
  const clipIndex = React.useMemo(() => {
    const m = new Map<string, { clip: MediaClip; track: MediaTrack }>();
    for (const t of tracks) for (const c of t.clips) m.set(c.id, { clip: c, track: t });
    return m;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rows]);

  // ── Seleção: atributo no DOM, não dado da lib ───────────────────────────────
  const selectedIds = React.useMemo(() => {
    const s = new Set(selected ?? []);
    for (const t of tracks) for (const c of t.clips) if (c.selected) s.add(c.id);
    return s;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected, rows]);
  // O clipe desenhado depois (janela nova, rolagem) já nasce marcado pelo `getActionRender`.
  const selectedNow = React.useRef(selectedIds);
  selectedNow.current = selectedIds;
  React.useLayoutEffect(() => {
    tl.box.current?.querySelectorAll<HTMLElement>("[data-mt-clip]").forEach((el) => {
      const on = selectedIds.has(el.dataset.mtClip!);
      if (el.hasAttribute("data-selected") !== on) el.toggleAttribute("data-selected", on);
    });
  }, [selectedIds, tl.box]);
  const kinds = [...new Set(tracks.flatMap((t) => t.clips.map((c) => c.kind ?? "clip")))].sort().join(",");
  const effects = React.useMemo(() => Object.fromEntries(kinds.split(",").map((k) => [k, { id: k }])), [kinds]);
  const geometry = React.useMemo(() => {
    let top = 0;
    return tracks.map((t) => { const h = t.height ?? trackHeight; const g = { id: t.id, top, h }; top += h; return g; });
  }, [tracks, trackHeight]);

  // ── Geometria e ímã ─────────────────────────────────────────────────────────
  const trackAtY = (y: number) => {
    const yy = y - TRACKS_TOP + tl.scrollTop.current;
    return geometry.find((g) => yy >= g.top && yy < g.top + g.h) ?? null;
  };
  const local = (e: { clientX: number; clientY: number }) => {
    const r = tl.box.current!.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const snapped = (t: number, free: boolean, extra: number[] = []) => {
    if (!snap || free) return { t, snapped: false };
    const p = snapTo(t, extra.length ? [...snapPoints, ...extra] : snapPoints, snapPx / pxPerSecond);
    return p === null ? { t, snapped: false } : { t: p, snapped: true };
  };
  const onFrame = (t: number) => Math.round(t * fps) / fps;
  // A faixa sob o mouse acende também o cabeçalho dela.
  const markHeader = (id: string | null) => {
    headers.current?.querySelectorAll<HTMLElement>("[data-track]").forEach((el) => el.toggleAttribute("data-hover", el.dataset.track === id));
  };
  const clearHover = () => { overlay.current?.set({ ghost: null, hoverTrack: null, razor: null, tip: null }); markHeader(null); };

  // ── Agulha: arrastar na régua é scrub contínuo; Alt solta do ímã ─────────────
  const dragPlayhead = (e: React.PointerEvent) => {
    // Sem preventDefault: o clique na régua precisa tirar o foco de um campo, senão o Ctrl+Z
    // seguinte vai para o campo e não para a timeline.
    const focus = document.activeElement as HTMLElement | null;
    if (focus?.closest("input, textarea, [contenteditable=\"true\"]")) focus.blur();
    onScrubStart?.();
    let last = clock.get();
    overlay.current?.set({ ghost: null });
    const move = (ev: PointerEvent | React.PointerEvent) => {
      const g = snapped(tl.timeAtX(local(ev).x), ev.altKey);
      // Só o relógio anda: quem usa re-renderiza uma vez, ao soltar.
      last = Math.max(0, Math.min(duration, g.t));
      clock.set(last);
      overlay.current?.set({ scrub: { snapped: g.snapped } });
      onScrub?.(last);
    };
    const up = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      overlay.current?.set({ scrub: null });
      onScrubEnd?.(last);
    };
    move(e);
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };

  // ── Seleção por área: pega, ao vivo, os clipes que o retângulo toca ───────────
  const selectByArea = (e: React.PointerEvent) => {
    // O começo fica no conteúdo (com a rolagem), para o retângulo crescer com a rolagem automática.
    const p0 = local(e);
    const ini = { x: p0.x + tl.scrollLeft.current, y: p0.y + tl.scrollTop.current };
    const additive = e.shiftKey || e.ctrlKey || e.metaKey;
    let moved = false, last = p0, frame = 0, dirty = false;
    let marked = new Set<string>();
    let picked: Set<string> | null = null;
    const box = tl.box.current!;
    // Os clipes desenhados, indexados uma vez (uma busca no DOM por clipe custava ~8 ms ao soltar
    // com 300 clipes). A rolagem real pode trocar a janela desenhada: aí o índice é refeito.
    let drawn: Map<string, Element> | null = null;
    const mark = (id: string, on: boolean) => {
      if (!drawn) { drawn = new Map(); box.querySelectorAll<HTMLElement>("[data-mt-clip]").forEach((el) => drawn!.set(el.dataset.mtClip!, el)); }
      drawn.get(id)?.toggleAttribute("data-in-marquee", on);
    };
    // O retângulo é um elemento só do DOM, criado no gesto: sem estado do React a cada movimento.
    let rect: HTMLDivElement | null = null;
    // Rolagem automática do gesto: o quanto a vista andou além da rolagem real (px). Rolar a grade
    // da lib re-renderiza todas as ações a cada passo (o cache de células dela não vale, porque a
    // lib clona cada linha); então o conteúdo anda por `translate` e a rolagem real só entra quando
    // o desvio passa do limite (a janela desenhada tem folga para isso) ou ao soltar.
    const grid = box.querySelector<HTMLElement>(".timeline-editor-edit-area .ReactVirtualized__Grid");
    const maxX = grid ? grid.scrollWidth - grid.clientWidth : 0, maxY = grid ? grid.scrollHeight - grid.clientHeight : 0;
    const off = { x: 0, y: 0 };
    const sl = () => tl.scrollLeft.current + off.x, st = () => tl.scrollTop.current + off.y;
    const shift = () => {
      const on = off.x !== 0 || off.y !== 0;
      const set = (el: Element | null | undefined, v: string) => { if (el) (el as HTMLElement).style.translate = on ? v : ""; };
      set(grid?.firstElementChild, `${-off.x}px ${-off.y}px`);
      set(box.querySelector(".timeline-editor-time-area .ReactVirtualized__Grid__innerScrollContainer"), `${-off.x}px 0`);
      const over = box.querySelector(".mt-overlay");
      set(over, `${-off.x}px 0`);
      over?.querySelectorAll(".mt-empty-hint").forEach((h) => set(h, `${off.x}px ${-off.y}px`));
      if (headers.current) headers.current.scrollTop = st();
    };
    const flush = () => {
      if (!grid || (off.x === 0 && off.y === 0)) return;
      const l = sl(), t = st();
      off.x = 0; off.y = 0;
      shift();
      // As refs já valem a rolagem nova (o evento de rolagem chega depois e confirma).
      tl.scrollLeft.current = l; tl.scrollTop.current = t;
      grid.scrollLeft = l; grid.scrollTop = t;
      drawn = null;
    };
    const update = () => {
      const p = last;
      const ax = ini.x - sl(), ay = ini.y - st();
      const x = Math.max(0, Math.min(ax, p.x)), y = Math.max(TRACKS_TOP, Math.min(ay, p.y));
      const r = { x, y, w: Math.max(0, Math.min(width, Math.max(ax, p.x)) - x), h: Math.max(0, Math.max(ay, p.y) - y) };
      if (!rect) { rect = document.createElement("div"); rect.className = "mt-marquee"; rect.setAttribute("aria-hidden", ""); box.appendChild(rect); }
      rect.style.transform = `translate(${r.x}px, ${r.y}px)`;
      rect.style.width = `${r.w}px`; rect.style.height = `${r.h}px`;
      // Acertos pela geometria (faixas e tempos), sem ler o layout de cada clipe.
      const ids = new Set<string>();
      const cx0 = r.x + sl(), cx1 = cx0 + r.w;
      const cy0 = r.y - TRACKS_TOP + st(), cy1 = cy0 + r.h;
      tracks.forEach((t, i) => {
        const g = geometry[i];
        if (g.top >= cy1 || g.top + g.h <= cy0 || t.locked) return;
        for (const c of t.clips) {
          if (c.selectable === false) continue;
          const x0 = startLeft + c.start * pxPerSecond, x1 = Math.max(x0 + 6, startLeft + c.end * pxPerSecond);
          if (x1 >= cx0 && x0 <= cx1) ids.add(c.id);
        }
      });
      // Durante o gesto, a seleção é só visual (atributo no DOM, trocando só o que mudou); quem usa
      // recebe uma vez, ao soltar. Antes, cada quadro re-renderizava todas as ações.
      const now = expandArea ? expandArea(ids) : ids;
      for (const k of marked) if (!now.has(k)) mark(k, false);
      for (const k of now) if (!marked.has(k)) mark(k, true);
      marked = now;
      inMarquee.current = now;
      picked = ids;
    };
    // Rolagem automática perto da borda (pelo desvio `off`, ver acima).
    const roll = () => {
      const p = last, edge = 28, high = box.clientHeight;
      const dx = p.x < edge ? p.x - edge : p.x > width - edge ? p.x - (width - edge) : 0;
      const dy = p.y < TRACKS_TOP + edge && p.y < ini.y - st() ? p.y - TRACKS_TOP - edge : p.y > high - edge ? p.y - (high - edge) : 0;
      const step = (d: number) => Math.sign(d) * Math.max(1, Math.abs(d * 0.4));
      const clamp = (v: number, real: number, max: number) => Math.max(-real, Math.min(max - real, v));
      const nx = dx ? clamp(off.x + step(dx), tl.scrollLeft.current, maxX) : off.x;
      const ny = dy ? clamp(off.y + step(dy), tl.scrollTop.current, maxY) : off.y;
      const rolled = nx !== off.x || ny !== off.y;
      if (rolled) {
        off.x = nx; off.y = ny;
        // Na horizontal a régua da lib só desenha as marcas à vista: o desvio fica curto.
        if (Math.abs(off.x) > 64 || Math.abs(off.y) > (high - TRACKS_TOP) / 2) flush(); else shift();
      }
      // No máximo uma conta por quadro, mesmo com o mouse mandando vários movimentos.
      if (rolled || dirty) { dirty = false; update(); }
      frame = requestAnimationFrame(roll);
    };
    const move = (ev: PointerEvent) => {
      last = local(ev);
      if (!moved && Math.hypot(last.x - p0.x, last.y - p0.y) < 4) return;
      if (!moved) { clearHover(); frame = requestAnimationFrame(roll); }
      moved = true;
      areaActive.current = true;
      dirty = true;
    };
    const up = () => {
      cancelAnimationFrame(frame);
      if (dirty) update();
      flush();
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      rect?.remove();
      areaActive.current = false;
      inMarquee.current = new Set();
      for (const k of marked) mark(k, false);
      if (moved) marqueeAt.current = performance.now();
      if (moved && picked) onAreaSelect?.(picked, { additive });
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };

  // ── Ponteiro na área: régua, vazio, navalha e hover ──────────────────────────
  const clipUnder = (el: HTMLElement) => {
    const id = el.closest<HTMLElement>("[data-mt-clip]")?.dataset.mtClip;
    return id ? clipIndex.get(id) ?? null : null;
  };
  const pointer = {
    onPointerDown: (e: React.PointerEvent) => {
      if (e.button !== 0) return;
      const el = e.target as HTMLElement;
      if (el.closest(".timeline-editor-time-area")) { dragPlayhead(e); return; }
      const hit = clipUnder(el);
      if (tool === "razor") {
        if (hit && !hit.track.locked && hit.clip.selectable !== false) onCut?.(hit.clip, hit.track.id, snapped(onFrame(tl.timeAtX(local(e).x)), e.altKey, [clock.get()]).t);
        return;
      }
      if (el.closest(".timeline-editor-edit-area") && !el.closest(".timeline-editor-action")) selectByArea(e);
    },
    onPointerMove: (e: React.PointerEvent) => {
      const now = overlay.current?.get();
      if (e.buttons && (now?.scrub || areaActive.current || now?.hud)) return;
      const p = local(e);
      const onRuler = p.y < RULER_HEIGHT;
      const t = onRuler ? null : trackAtY(p.y);
      const hit = onRuler ? null : clipUnder(e.target as HTMLElement);
      // Clipe estreito (o nome não cabe): dica com nome, início e duração em cima dele.
      let tip = null;
      const action = hit?.clip.name ? (e.target as HTMLElement).closest<HTMLElement>(".timeline-editor-action") : null;
      if (hit && action && !e.buttons && action.offsetWidth < 64) {
        const r = action.getBoundingClientRect(), b = tl.box.current!.getBoundingClientRect();
        tip = { x: r.left - b.left + r.width / 2, y: r.top - b.top, name: hit.clip.name!, start: hit.clip.start, duration: hit.clip.end - hit.clip.start };
      }
      overlay.current?.set({
        ghost: onRuler ? tl.timeAtX(p.x) : null,
        hoverTrack: t?.id ?? null,
        razor: tool === "razor" && t && hit && hit.clip.selectable !== false ? { t: snapped(onFrame(tl.timeAtX(p.x)), e.altKey, [clock.get()]).t, track: t.id } : null,
        tip,
      });
      markHeader(t?.id ?? null);
    },
    onPointerLeave: clearHover,
  };

  // HUD do arrasto e do aparo: início, duração e o quanto andou desde que pegou.
  const showHud = (action: TimelineAction, track: string, start: number, end: number, edge?: "left" | "right") => {
    const o = clipIndex.get(action.id)?.clip;
    if (!o) return;
    const delta = edge === "right" ? (end - start) - (o.end - o.start) : start - o.start;
    overlay.current?.set({ hud: { track, start, duration: end - start, delta }, ghost: null, razor: null });
  };

  // ── Teclado próprio (opcional) ──────────────────────────────────────────────
  React.useEffect(() => {
    if (!keyboard) return;
    const key = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).closest("input, textarea, [contenteditable=\"true\"], [role=dialog]") || e.ctrlKey || e.metaKey) return;
      const k = e.key.toLowerCase();
      if (e.key === "=" || e.key === "+") tl.zoomTo(tl.zoomTarget() * 1.5);
      else if (e.key === "-" || e.key === "_") tl.zoomTo(tl.zoomTarget() / 1.5);
      else if (k === "z" && e.shiftKey) tl.fit();
      else if (k === "v") onToolChange?.("select");
      else if (k === "c") onToolChange?.("razor");
    };
    window.addEventListener("keydown", key);
    return () => window.removeEventListener("keydown", key);
  });

  // Os eventos da lib passam por uma ref: o elemento da lib fica memorizado (abaixo) e não pode
  // segurar funções de um render velho.
  const live = {
    clickAction: (e: React.MouseEvent<HTMLElement, MouseEvent>, action: TimelineAction, row: TimelineRow) => { const hit = clipIndex.get(action.id); if (hit) onClipClick?.(hit.clip, row.id, e); },
    clickRow: (e: React.MouseEvent<HTMLElement, MouseEvent>) => {
      // Clique no vazio da faixa (menos logo depois de uma seleção por área).
      if (performance.now() - marqueeAt.current < 300) return;
      if (!(e.target as HTMLElement).closest(".mt-clip")) onEmptyClick?.(e);
    },
    moving: (action: TimelineAction, row: TimelineRow, start: number, end: number) => { showHud(action, row.id, start, end); },
    resizing: (action: TimelineAction, row: TimelineRow, start: number, end: number, dir: "left" | "right") => { showHud(action, row.id, start, end, dir); },
    moveEnd: (action: TimelineAction, row: TimelineRow, start: number, end: number) => {
      overlay.current?.set({ hud: null });
      const hit = clipIndex.get(action.id);
      if (hit) onMove?.({ clip: hit.clip, track: row.id, start, end });
    },
    resizeEnd: (action: TimelineAction, row: TimelineRow, start: number, end: number, dir: "left" | "right") => {
      overlay.current?.set({ hud: null });
      const hit = clipIndex.get(action.id);
      if (hit) onResize?.({ clip: hit.clip, track: row.id, start, end, edge: dir });
    },
    scroll: (scrollTop: number, scrollLeft: number) => {
      tl.scrollLeft.current = scrollLeft; tl.scrollTop.current = scrollTop;
      overlay.current?.set({ left: scrollLeft, top: scrollTop });
      if (headers.current) headers.current.scrollTop = scrollTop;
      onScroll?.({ left: scrollLeft, top: scrollTop });
    },
  };
  const liveRef = React.useRef(live);
  liveRef.current = live;
  // A lib re-renderiza todas as ações a cada render de quem a contém (não é memorizada): o
  // elemento dela só muda quando muda o que ela desenha. Um render de quem usa que só trocou a
  // seleção, o painel ou o HUD não chega às 300 ações.
  const lib = React.useMemo(() => (
      <VisibleTimeline ref={tl.timeline} anchor={tl.anchor.current} style={{ width: "100%", height: "100%" }} editorData={rows} effects={effects}
        // Régua que se adapta ao zoom: segundos longe, meio segundo, quadros de perto.
        scale={ruler.step} scaleWidth={pxPerSecond * ruler.step} scaleSplitCount={ruler.divisions} startLeft={startLeft} rowHeight={trackHeight}
        minScaleCount={ruler.count} maxScaleCount={ruler.count} autoScroll gridSnap={snap} dragLine={snap}
        // A agulha é a da camada por cima (arrasta pela régua, gruda, tem HUD).
        hideCursor disableDrag={tool === "razor"}
        getScaleRender={(s) => <span className="mt-num">{rulerLabel(s, fps)}</span>}
        getActionRender={(a, row) => {
          const hit = clipIndex.get(a.id);
          if (!hit) return null;
          return (
            <span className="mt-clip" data-mt-clip={a.id} data-selected={selectedNow.current.has(a.id) ? "" : undefined}
              data-in-marquee={inMarquee.current.has(a.id) ? "" : undefined}>
              {renderClip(hit.clip, row.id, { px: (a.end - a.start) * pxPerSecond })}
            </span>
          );
        }}
        onClickActionOnly={(e, { action, row }) => liveRef.current.clickAction(e, action, row)}
        onClickRow={(e) => liveRef.current.clickRow(e)}
        onActionMoving={({ action, row, start, end }) => { liveRef.current.moving(action, row, start, end); }}
        onActionResizing={({ action, row, start, end, dir }) => { liveRef.current.resizing(action, row, start, end, dir); }}
        onActionMoveEnd={({ action, row, start, end }) => liveRef.current.moveEnd(action, row, start, end)}
        onActionResizeEnd={({ action, row, start, end, dir }) => liveRef.current.resizeEnd(action, row, start, end, dir)}
        onScroll={({ scrollTop, scrollLeft }) => liveRef.current.scroll(scrollTop, scrollLeft)} />
    // eslint-disable-next-line react-hooks/exhaustive-deps
  ), [rows, effects, ruler.step, ruler.divisions, ruler.count, pxPerSecond, startLeft, trackHeight, snap, tool, fps, clipIndex, renderClip]);
  // (A âncora do zoom só vale no render da escala nova, e `pxPerSecond` já está nas dependências.)

  const head = (
    <TrackHeaders ref={headers} top={TRACKS_TOP} className={headersClassName} labels={headerLabels}
      tracks={tracks.map((t) => ({ ...t, height: t.height ?? trackHeight }))} state={trackState}
      selected={selectedTracks ?? new Set()} editing={editingTrack}
      onEdit={props.onTrackEdit ?? nada} onRename={props.onTrackRename ?? nada} onSelect={props.onTrackSelect ?? nada}
      onLock={props.onTrackLock ?? nada} onMute={props.onTrackMute ?? nada} onSolo={props.onTrackSolo ?? nada}
      onCollapse={props.onTrackCollapse ?? nada} onHide={props.onTrackHide} />
  );
  const area = (
    <div ref={tl.box} className={cn("mt-viewport", tool === "razor" && "is-razor", areaClassName)} {...pointer}>
      {lib}
      <Overlay ref={overlay} startLeft={startLeft} pxPerSecond={pxPerSecond} clock={clock} duration={duration} width={width} geometry={geometry}
        step={ruler.step} fps={fps} formatTime={formatTime} hints={emptyHints} />
    </div>
  );
  return (
    <div className={cn("mt", className)}>
      {wrapHeaders ? wrapHeaders(head) : head}
      {wrapArea ? wrapArea(area) : area}
    </div>
  );
}

import * as React from "react";
import type { TimelineState } from "@xzdarcy/react-timeline-editor";
import type { Clock } from "./clock";
import { rulerScale } from "./ruler";

// O estado de vista da timeline: zoom, px por segundo, régua, rolagem e a âncora do zoom. Fica num
// hook (e não dentro do componente) porque quem usa precisa dele fora da timeline: o play rola a
// vista, a tira de quadros mede pelo px por segundo, o slider de zoom mora numa barra.

export interface UseMediaTimelineOptions {
  /** Duração do filme (s). */
  duration: number;
  /** O relógio do play: o zoom sem ponteiro ancora na agulha. */
  clock: Clock;
  /** Folga à esquerda do tempo zero (px). */
  startLeft?: number;
  /** Mínimo de px por segundo, mesmo com o zoom de caber. */
  minPxPerSecond?: number;
  maxZoom?: number;
  fps?: number;
  /** Quanto o gesto espera depois do último passo para aplicar a escala (ms). */
  settleMs?: number;
}

export type MediaTimelineController = ReturnType<typeof useMediaTimeline>;

export function useMediaTimeline({ duration, clock, startLeft = 12, minPxPerSecond = 24, maxZoom = 48, fps = 30, settleMs = 140 }: UseMediaTimelineOptions) {
  const total = duration || 1;
  const timeline = React.useRef<TimelineState>(null);
  const box = React.useRef<HTMLDivElement>(null);
  const scrollLeft = React.useRef(0);
  const scrollTop = React.useRef(0);
  const anchor = React.useRef<{ t: number; x: number } | null>(null);
  const [width, setWidth] = React.useState(1200);
  const [zoom, setZoom] = React.useState(1);
  const pxPerSecond = Math.max(minPxPerSecond, ((width - 40) / total) * zoom);
  const ppsRef = React.useRef(pxPerSecond);
  ppsRef.current = pxPerSecond;
  const widthRef = React.useRef(width);
  widthRef.current = width;
  const zoomRef = React.useRef(zoom);
  zoomRef.current = zoom;
  const ruler = rulerScale(pxPerSecond, total, fps);
  const ppsAt = (z: number) => Math.max(minPxPerSecond, ((widthRef.current - 40) / total) * z);
  const setScroll = (x: number) => timeline.current?.setScrollLeft(Math.max(0, x));

  // Depois do zoom, rola para o tempo da âncora voltar ao mesmo x (mouse, agulha ou meio).
  React.useLayoutEffect(() => {
    const a = anchor.current;
    if (!a) return;
    anchor.current = null;
    setScroll(startLeft + a.t * pxPerSecond - a.x);
    stretch(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pxPerSecond]);

  // Zoom em gesto: durante a roda, as teclas ou o slider, a timeline estica por `transform` em
  // volta da âncora, sem re-renderizar as ações; a escala de verdade entra uma vez, `settleMs`
  // depois do último passo. Com 300 clipes, cada passo custava ~70 ms de render.
  const gesture = React.useRef<{ target: number; t: number; x: number; timer: number } | null>(null);
  const stretch = (s: number | null, x = 0) => {
    const el = box.current;
    if (!el) return;
    el.querySelectorAll<HTMLElement>(".ReactVirtualized__Grid__innerScrollContainer").forEach((a) => {
      a.style.transformOrigin = s === null ? "" : `${x + scrollLeft.current}px 0`;
      a.style.transform = s === null ? "" : `scaleX(${s})`;
    });
    const over = el.querySelector<HTMLElement>(".mt-overlay");
    if (over) { over.style.transformOrigin = s === null ? "" : `${x}px 0`; over.style.transform = s === null ? "" : `scaleX(${s})`; }
  };
  const gestureZoom = (z: number, at: { t: number; x: number }) => {
    const g = gesture.current ?? { target: zoomRef.current, ...at, timer: 0 };
    g.target = Math.max(1, Math.min(maxZoom, z));
    gesture.current = g;
    stretch(ppsAt(g.target) / ppsRef.current, g.x);
    window.clearTimeout(g.timer);
    g.timer = window.setTimeout(() => {
      const f = gesture.current;
      gesture.current = null;
      if (!f) return;
      if (Math.abs(ppsAt(f.target) - ppsRef.current) < 0.01) { stretch(null); return; }
      anchor.current = { t: f.t, x: f.x };
      setZoom(f.target);
    }, settleMs);
  };
  const gestureRef = React.useRef(gestureZoom);
  gestureRef.current = gestureZoom;
  /** O zoom para onde o gesto está indo (ou o atual): teclas e roda somam sobre ele. */
  const zoomTarget = () => gesture.current?.target ?? zoomRef.current;
  const zoomTargetRef = React.useRef(zoomTarget);
  zoomTargetRef.current = zoomTarget;
  /** Zoom em volta do x (px na vista); sem x, em volta da agulha (ou do meio, se ela está fora). */
  const zoomTo = (z: number, x?: number) => {
    const now = clock.get();
    const xA = startLeft + now * ppsRef.current - scrollLeft.current;
    gestureZoom(z, x !== undefined
      ? { t: (x + scrollLeft.current - startLeft) / ppsRef.current, x }
      : { t: now, x: xA >= 0 && xA <= widthRef.current ? xA : widthRef.current / 2 });
  };
  const fit = () => { anchor.current = { t: 0, x: startLeft }; setZoom(1); setScroll(0); };

  // Largura da área e Ctrl+roda (zoom em volta do mouse; listener não passivo para segurar o zoom
  // da página).
  React.useEffect(() => {
    const el = box.current;
    if (!el) return;
    const o = new ResizeObserver(([e]) => setWidth(e.contentRect.width));
    o.observe(el);
    const wheel = (e: WheelEvent) => {
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();
      const x = e.clientX - el.getBoundingClientRect().left;
      gestureRef.current(zoomTargetRef.current() * (e.deltaY < 0 ? 1.15 : 1 / 1.15), { t: (x + scrollLeft.current - startLeft) / ppsRef.current, x });
    };
    el.addEventListener("wheel", wheel, { passive: false });
    return () => { o.disconnect(); el.removeEventListener("wheel", wheel); };
  }, [startLeft]);

  /** A agulha nunca some: saiu da vista, a timeline vira a página (como nos editores de vídeo). */
  const reveal = React.useCallback((t: number) => {
    const x = startLeft + t * ppsRef.current, left = scrollLeft.current, w = widthRef.current;
    if (x < left) setScroll(x - w * 0.85);
    else if (x > left + w - 16) setScroll(x - w * 0.15);
  }, [startLeft]);
  /** No play: a vista segue a agulha quando ela chega perto da borda. */
  const follow = React.useCallback((t: number) => {
    const x = startLeft + t * ppsRef.current;
    if (x > scrollLeft.current + widthRef.current - 80 || x < scrollLeft.current) setScroll(x - 80);
  }, [startLeft]);
  /** O tempo (s) num x da vista, dentro do filme. */
  const timeAtX = (x: number) => Math.max(0, Math.min(total, (x + scrollLeft.current - startLeft) / ppsRef.current));

  return {
    duration: total, startLeft, fps, maxZoom,
    zoom, zoomTo, zoomTarget, fit, pxPerSecond, ruler, width,
    reveal, follow, timeAtX, setScroll,
    /** Refs que a timeline preenche: quem usa lê, não escreve. */
    timeline, box, scrollLeft, scrollTop, anchor,
  };
}

import * as React from "react";
import { Timeline, type TimelineState } from "@xzdarcy/react-timeline-editor";
import type { TimelineRow } from "@xzdarcy/timeline-engine";

// Virtualização das ações. A lib (`@xzdarcy/react-timeline-editor`) só virtualiza as linhas
// (react-virtualized, overscan de 10): cada linha desenha todas as suas ações, e a cada mudança
// de escala ou de dados todas re-renderizam. Esta camada passa para a lib só as ações dentro da
// janela rolada, com uma tela de folga para cada lado, e só troca a janela quando a vista chega a
// meia tela da borda (histerese: rolar não pisca nem remonta a cada passo). Medido num filme de
// 300 clipes: zoom de 83 para 89 fps, rolagem de 89 para 92, 2.444 para 1.607 nós de perto.

/** O que está à vista: tempo em segundos e altura em px do conteúdo. */
export interface View { t0: number; t1: number; y0: number; y1: number }

export function viewOf(left: number, top: number, width: number, height: number, pxPerSecond: number, startLeft: number): View {
  return { t0: (left - startLeft) / pxPerSecond, t1: (left + width - startLeft) / pxPerSecond, y0: top, y1: top + height };
}

/** A janela desenhada: a vista com uma tela de folga para cada lado. */
export function windowOf(v: View): View {
  const dt = v.t1 - v.t0, dy = v.y1 - v.y0;
  return { t0: v.t0 - dt, t1: v.t1 + dt, y0: v.y0 - dy, y1: v.y1 + dy };
}

/** Troca quando a vista chega a meia tela da borda da janela, ou quando a janela ficou larga
 *  demais para a vista (depois de aproximar o zoom, ela desenharia o filme quase inteiro). */
export function needsNewWindow(w: View, v: View): boolean {
  const dt = v.t1 - v.t0, dy = v.y1 - v.y0;
  return v.t0 < w.t0 + dt / 2 || v.t1 > w.t1 - dt / 2 || w.t1 - w.t0 > dt * 6
    || v.y0 < w.y0 + dy / 2 || v.y1 > w.y1 - dy / 2 || w.y1 - w.y0 > dy * 6;
}

/** As linhas com só as ações da janela (e as fixas, como a que está sendo arrastada). Linha fora
 *  da janela fica, com a mesma altura, sem ações. Nada cortado devolve o mesmo array. */
export function cropRows(rows: TimelineRow[], w: View, defaultHeight: number, pinned: ReadonlySet<string>): TimelineRow[] {
  let top = 0, changed = false;
  const out = rows.map((r) => {
    const h = r.rowHeight ?? defaultHeight;
    const inside = top < w.y1 && top + h > w.y0;
    top += h;
    const actions = r.actions.filter((a) => pinned.has(a.id) || (inside && a.end >= w.t0 && a.start <= w.t1));
    if (actions.length === r.actions.length) return r;
    changed = true;
    return { ...r, actions };
  });
  return changed ? out : rows;
}

export type VisibleTimelineProps = React.ComponentProps<typeof Timeline> & {
  /** Depois de uma troca de escala, o tempo `t` fica no x `x` da vista (o zoom ancorado). A
   *  janela já nasce certa no mesmo render, sem desenhar primeiro a da escala velha. */
  anchor?: { t: number; x: number } | null;
};

/** A `Timeline` da lib com as ações fora da vista fora do DOM. Mesma API, mais `anchor`. */
export const VisibleTimeline = React.forwardRef<TimelineState, VisibleTimelineProps>(function VisibleTimeline({ anchor, ...props }, ref) {
  const { editorData, scale = 1, scaleWidth = 160, startLeft = 20, rowHeight = 32 } = props;
  const pps = scaleWidth / scale;
  const inner = React.useRef<TimelineState>(null);
  // Sem dependências: a lib refaz o objeto dela a cada render, e quem chama deve ver o atual.
  React.useImperativeHandle(ref, () => inner.current as TimelineState);
  const scroll = React.useRef({ left: 0, top: 0 });
  const size = React.useRef({ width: 0, height: 0 });
  const pinned = React.useRef(new Set<string>());
  const win = React.useRef<View | null>(null);
  const seenPps = React.useRef(pps);
  const [, refresh] = React.useReducer((n: number) => n + 1, 0);

  // Escala nova: a rolagem que vai valer é a da âncora (quem chama rola para lá logo depois).
  let newScale = false;
  if (pps !== seenPps.current) {
    seenPps.current = pps;
    newScale = true;
    if (anchor) scroll.current = { ...scroll.current, left: Math.max(0, startLeft + anchor.t * pps - anchor.x) };
  }
  const viewNow = () => viewOf(scroll.current.left, scroll.current.top, size.current.width, size.current.height, pps, startLeft);
  if (size.current.width > 0) {
    const v = viewNow();
    if (!win.current || newScale || needsNewWindow(win.current, v)) win.current = windowOf(v);
  }
  const w = win.current;
  const data = React.useMemo(() => (w ? cropRows(editorData, w, rowHeight, pinned.current) : editorData), [editorData, w, rowHeight]);

  // Medida da área: sem ela (1º render), desenha tudo, como a lib sozinha.
  React.useEffect(() => {
    const el = inner.current?.target;
    if (!el) return;
    const o = new ResizeObserver(() => {
      const r = el.getBoundingClientRect();
      if (r.width === size.current.width && r.height === size.current.height) return;
      size.current = { width: r.width, height: r.height };
      refresh();
    });
    o.observe(el);
    return () => o.disconnect();
  }, []);

  const { onScroll, onActionMoveStart, onActionResizeStart, onActionMoveEnd, onActionResizeEnd } = props;
  return (
    <Timeline ref={inner} {...props} editorData={data}
      onScroll={(p) => {
        scroll.current = { left: p.scrollLeft, top: p.scrollTop };
        onScroll?.(p);
        if (win.current && size.current.width > 0 && needsNewWindow(win.current, viewNow())) refresh();
      }}
      // A ação arrastada fica desenhada até soltar, mesmo que a rolagem automática leve a janela
      // para longe do lugar original dela (a lib precisa dela nos dados para fechar o arrasto).
      onActionMoveStart={(d) => { pinned.current.add(d.action.id); return onActionMoveStart?.(d); }}
      onActionResizeStart={(d) => { pinned.current.add(d.action.id); return onActionResizeStart?.(d); }}
      onActionMoveEnd={(d) => { pinned.current.delete(d.action.id); return onActionMoveEnd?.(d); }}
      onActionResizeEnd={(d) => { pinned.current.delete(d.action.id); return onActionResizeEnd?.(d); }} />
  );
});

import * as React from "react";
import { cn } from "@/lib/utils";
import { useClockTime, type Clock } from "./clock";
import { formatSeconds, rulerLabel } from "./ruler";

// A camada por cima da timeline da lib: agulha própria, agulha fantasma da régua, faixa sob o
// mouse, linha da navalha, HUD do arrasto e dica do clipe estreito.
// A lib continua dona dos clipes (arrastar, aparar); isto só desenha. Guarda o próprio estado e
// muda por `set`, sem renderizar quem usa a timeline a cada movimento do mouse.

/** Altura da régua da lib (32) mais a margem de cima da área das faixas (10). */
export const TRACKS_TOP = 42;
export const RULER_HEIGHT = 32;
/** Largura que um rótulo da régua ocupa (para não cortar na borda direita). */
const LABEL_PX = 34;

export interface OverlayState {
  left: number; top: number;
  ghost: number | null;
  hoverTrack: string | null;
  scrub: { snapped: boolean } | null;
  razor: { t: number; track: string } | null;
  hud: { track: string; start: number; duration: number; delta: number } | null;
  /** Dica do clipe estreito sob o mouse (nome, início, duração), presa no topo dele. */
  tip: { x: number; y: number; name: string; start: number; duration: number } | null;
}
export interface OverlayHandle { set: (p: Partial<OverlayState>) => void; get: () => OverlayState }
export interface TrackGeometry { id: string; top: number; h: number }
const EMPTY: OverlayState = { left: 0, top: 0, ghost: null, hoverTrack: null, scrub: null, razor: null, hud: null, tip: null };

export const Overlay = React.forwardRef<OverlayHandle, {
  startLeft: number; pxPerSecond: number; duration: number; width: number; geometry: TrackGeometry[];
  clock: Clock;
  /** Intervalo entre dois números da régua (s). */
  step: number;
  fps: number;
  formatTime: (t: number) => string;
  /** Frase das faixas vazias, no começo da área visível. */
  hints?: { track: string; text: string }[];
}>(function Overlay({ startLeft, pxPerSecond, clock, duration, width, geometry, step, fps, formatTime, hints = [] }, ref) {
  const [s, setS] = React.useState<OverlayState>(EMPTY);
  const current = React.useRef(s);
  current.current = s;
  React.useImperativeHandle(ref, () => ({
    set: (p) => setS((v) => {
      const n = { ...v, ...p };
      return (Object.keys(p) as (keyof OverlayState)[]).every((k) => v[k] === n[k]) ? v : n;
    }),
    get: () => current.current,
  }), []);
  const xOf = (t: number) => startLeft + t * pxPerSecond - s.left;
  const inView = (x: number) => x >= 0 && x <= width;
  const g = (id: string | null) => (id ? geometry.find((x) => x.id === id) ?? null : null);
  const topOf = (l: TrackGeometry) => TRACKS_TOP + l.top - s.top;
  const hover = g(s.hoverTrack);
  const razorTrack = s.razor ? g(s.razor.track) : null;
  const hudTrack = s.hud ? g(s.hud.track) : null;
  const hudY = hudTrack ? topOf(hudTrack) - 26 : 0;
  const below = hudTrack ? hudY < TRACKS_TOP : false;
  // Régua: o número fica logo à direita da marca (nada corta na borda esquerda) e some antes de
  // cortar na direita. Em quadros, o segundo inteiro vem em destaque e um rótulo fixo à esquerda
  // diz em que segundo se está, para nenhum "15f" ficar sem contexto.
  const tStart = Math.max(0, (s.left - startLeft) / pxPerSecond), tEnd = Math.min(duration, (s.left + width - startLeft) / pxPerSecond);
  const marks: { k: number; t: number; x: number; whole: boolean }[] = [];
  for (let k = Math.floor(tStart / step); k * step <= tEnd + 1e-6; k++) {
    const t = k * step, x = xOf(t) + 4;
    if (x < 0 || x + LABEL_PX > width) continue;
    marks.push({ k, t, x, whole: Math.abs(t - Math.round(t)) < 1e-6 });
  }
  const firstWhole = marks.find((m) => m.whole)?.x ?? Infinity;
  const context = step < 1 && firstWhole > LABEL_PX + 12 ? Math.floor(tStart + 1e-6) : null;
  const labels = marks.filter((m) => context === null || m.x > LABEL_PX + 4).map((m) => (
    <span key={m.k} className={cn("mt-ruler-label mt-num", m.whole && "is-whole")} style={{ transform: `translateX(${m.x}px)` }}>{rulerLabel(m.t, fps)}</span>
  ));
  return (
    <div aria-hidden className="mt-overlay">
      <div className="mt-ruler-labels">
        {labels}
        {context !== null ? <span className="mt-ruler-context mt-num">{rulerLabel(context, fps)}</span> : null}
      </div>
      {hints.map((h) => { const l = g(h.track); return l ? <span key={h.track} className="mt-empty-hint" style={{ transform: `translateY(${topOf(l)}px)`, height: l.h }}>{h.text}</span> : null; })}
      <div className="mt-overlay-tracks">
        {hover ? <div className="mt-hover-track" style={{ transform: `translateY(${hover.top - s.top}px)`, height: hover.h }} /> : null}
      </div>
      {s.ghost !== null && !s.scrub && inView(xOf(s.ghost)) ? (
        <div className="mt-ghost" style={{ transform: `translateX(${xOf(s.ghost)}px)` }}>
          <span className="mt-ghost-time mt-num">{formatTime(s.ghost)}</span>
        </div>
      ) : null}
      {s.razor && razorTrack && inView(xOf(s.razor.t)) ? (
        <div className="mt-razor" style={{ transform: `translate(${xOf(s.razor.t)}px, ${topOf(razorTrack)}px)`, height: razorTrack.h }}>
          <span className="mt-razor-time mt-num">{formatTime(s.razor.t)}</span>
        </div>
      ) : null}
      <Playhead clock={clock} x={xOf} width={width} duration={duration} scrub={s.scrub} formatTime={formatTime} />
      {s.tip && !s.scrub && !s.hud ? (
        <div className="mt-clip-tip" style={{ transform: `translate(${s.tip.x}px, ${s.tip.y}px)` }}>
          <span className="mt-clip-tip-name">{s.tip.name}</span>
          <span className="mt-num">{formatTime(s.tip.start)} · {formatSeconds(s.tip.duration)}</span>
        </div>
      ) : null}
      {s.hud && hudTrack ? (
        <div className="mt-hud mt-num" style={{ transform: `translate(${Math.max(4, xOf(s.hud.start))}px, ${below ? topOf(hudTrack) + hudTrack.h + 4 : hudY}px)` }}>
          <span>{formatTime(s.hud.start)}</span>
          <span className="mt-hud-sep" />
          <span>{formatSeconds(s.hud.duration)}</span>
          {Math.abs(s.hud.delta) > 0.0005 ? <><span className="mt-hud-sep" /><span className="mt-hud-delta">{formatSeconds(s.hud.delta, true)}</span></> : null}
        </div>
      ) : null}
    </div>
  );
});

/** A agulha é a única parte que redesenha a cada quadro do play (assina o relógio sozinha). */
function Playhead({ clock, x, width, duration, scrub, formatTime }: { clock: Clock; x: (t: number) => number; width: number; duration: number; scrub: { snapped: boolean } | null; formatTime: (t: number) => string }) {
  const time = useClockTime(clock);
  const xA = x(time);
  if (xA < 0 || xA > width || time > duration) return null;
  return (
    <div className={cn("mt-playhead", scrub && "is-dragging", scrub?.snapped && "is-snapped")} style={{ transform: `translateX(${xA}px)` }}>
      <span className="mt-playhead-head">{scrub ? <span className="mt-num">{formatTime(time)}</span> : null}</span>
    </div>
  );
}

import * as React from "react";
import { ChevronRight, EyeOff, Lock, LockOpen, Volume2, VolumeX } from "lucide-react";
