// Cabeçalhos das faixas: nome (renomeável no lugar), cor, solo, calar, esconder e travar, e os
// grupos que recolhem. Não sabe de dado: recebe as faixas e o estado por props e devolve cada
// gesto por callback.

export interface TrackHeader {
  id: string;
  label: string;
  height: number;
  /** Cor do ponto (valor CSS, de preferência um token). Sem cor, sem ponto. */
  color?: string;
  /** Cabeçalho de grupo: recolhido ou não, e quantas faixas tem. */
  group?: { collapsed: boolean; count: number };
  /** Faixa dentro de um grupo aberto: recua um passo. */
  nested?: boolean;
  /** Quais botões a linha tem. */
  controls?: { solo?: boolean; mute?: boolean; hide?: boolean; lock?: boolean };
  renamable?: boolean;
}
export interface TrackState { locked: boolean; muted: boolean; solo: boolean; hidden?: boolean }

export interface TrackHeaderLabels {
  list: string; name: string; solo: string; mute: string; unmute: string; hide: string;
  lock: string; unlock: string; expand: string; collapse: string; renameHint: string;
}
export const TRACK_HEADER_LABELS: TrackHeaderLabels = {
  list: "Faixas", name: "Nome da faixa", solo: "Solo em", mute: "Calar", unmute: "Ouvir", hide: "Esconder",
  lock: "Travar", unlock: "Destravar", expand: "Abrir", collapse: "Recolher", renameHint: "dois cliques ou F2 renomeiam",
};

export interface TrackHeadersProps {
  tracks: TrackHeader[];
  state: (id: string) => TrackState;
  selected: Set<string>;
  editing: string | null;
  /** Espaço em cima (a altura da régua), para as linhas casarem com as faixas. */
  top: number;
  className?: string;
  labels?: Partial<TrackHeaderLabels>;
  onEdit: (id: string | null) => void;
  onRename: (id: string, name: string) => void;
  onSelect: (id: string, additive: boolean) => void;
  onLock: (id: string) => void;
  onMute: (id: string) => void;
  onSolo: (id: string) => void;
  onCollapse: (id: string) => void;
  /** Tira a linha da timeline (quem chama decide onde ela continua aparecendo). */
  onHide?: (id: string) => void;
}

export const TrackHeaders = React.forwardRef<HTMLDivElement, TrackHeadersProps>(function TrackHeaders(
  { tracks, state, selected, editing, top, className, labels, onEdit, onRename, onSelect, onLock, onMute, onSolo, onCollapse, onHide }, ref) {
  const L = { ...TRACK_HEADER_LABELS, ...labels };
  return (
    <div ref={ref} role="listbox" aria-label={L.list} aria-multiselectable className={cn("mt-headers", className)} style={{ paddingTop: top }}>
      {tracks.map((t) => {
        const s = state(t.id);
        const c = t.controls ?? {};
        return (
          <div key={t.id} role="option" aria-selected={selected.has(t.id)} tabIndex={0} data-track={t.id} data-alvo={`faixa:${t.id}`}
            className={cn("mt-track-header", t.group && "is-group", t.nested && "is-nested", s.muted && "is-muted")}
            style={{ height: t.height }}
            onClick={(e) => { if (!(e.target as HTMLElement).closest("button, input")) onSelect(t.id, e.shiftKey || e.ctrlKey || e.metaKey); }}
            onDoubleClick={(e) => { if (t.renamable && !(e.target as HTMLElement).closest("button")) onEdit(t.id); }}
            onKeyDown={(e) => {
              if (e.target !== e.currentTarget) return;
              if (e.key === "F2" && t.renamable) { e.preventDefault(); e.stopPropagation(); onEdit(t.id); }
              else if ((e.key === "Enter" || e.key === " ") && t.group) { e.preventDefault(); e.stopPropagation(); onCollapse(t.id); }
            }}>
            {t.group ? (
              <button type="button" className="mt-track-chevron" aria-expanded={!t.group.collapsed} aria-label={`${t.group.collapsed ? L.expand : L.collapse} ${t.label}`} onClick={() => onCollapse(t.id)}>
                <ChevronRight className={cn(!t.group.collapsed && "rotate-90")} />
              </button>
            ) : t.color ? <span aria-hidden className="mt-track-dot" style={{ background: t.color }} /> : null}
            {editing === t.id
              ? <TrackRename value={t.label} label={L.name} onSave={(n) => { onRename(t.id, n); onEdit(null); }} onCancel={() => onEdit(null)} />
              : <span className="mt-track-name" title={t.renamable ? `${t.label} (${L.renameHint})` : t.label}>{t.label}{t.group ? <span className="mt-num mt-track-count"> {t.group.count}</span> : null}</span>}
            <span className="mt-track-actions">
              {c.solo ? <HeaderButton active={s.solo} label={`${L.solo} ${t.label}`} onClick={() => onSolo(t.id)}><span className="mt-track-solo">S</span></HeaderButton> : null}
              {c.mute ? <HeaderButton active={s.muted} label={`${s.muted ? L.unmute : L.mute} ${t.label}`} onClick={() => onMute(t.id)}>{s.muted ? <VolumeX /> : <Volume2 />}</HeaderButton> : null}
              {c.hide && onHide ? <HeaderButton active={false} label={`${L.hide} ${t.label}`} onClick={() => onHide(t.id)}><EyeOff /></HeaderButton> : null}
              {c.lock ? <HeaderButton active={s.locked} label={`${s.locked ? L.unlock : L.lock} ${t.label}`} onClick={() => onLock(t.id)}>{s.locked ? <Lock /> : <LockOpen />}</HeaderButton> : null}
            </span>
          </div>
        );
      })}
    </div>
  );
});

/** Edição no lugar: Enter grava, Esc cancela, sair do campo grava. */
export function TrackRename({ value, label, onSave, onCancel }: { value: string; label: string; onSave: (n: string) => void; onCancel: () => void }) {
  const [text, setText] = React.useState(value);
  const done = React.useRef(false);
  const save = () => { if (done.current) return; done.current = true; if (text.trim() === value) onCancel(); else onSave(text); };
  return (
    <InlineEdit isEditing value={value} onStartEdit={() => {}} className="min-w-0 flex-1 [--ie-h:1.5rem]"
      onSave={async () => save()} onCancel={() => { done.current = true; onCancel(); }}>
      <input autoFocus aria-label={label} value={text} maxLength={40} onChange={(e) => setText(e.target.value)}
        onFocus={(e) => e.currentTarget.select()} onBlur={save} className="mt-track-input" />
    </InlineEdit>
  );
}

function HeaderButton({ active, label, onClick, children }: { active: boolean; label: string; onClick: () => void; children: React.ReactNode }) {
  return (
    <button type="button" aria-label={label} aria-pressed={active} title={label} onClick={onClick} className="mt-track-button">
      {children}
    </button>
  );
}

// Régua que se adapta ao zoom (segundos de longe, meio segundo, quadros de perto), ímã e formatos
// de tempo. Funções puras: quem usa pode testar e reaproveitar sem o componente.

/** Distância mínima, em px, entre dois números da régua. */
const LABEL_SPACE = 64;

/** Os intervalos possíveis entre dois números da régua (s): quadros, depois segundos. */
const stepsFor = (fps: number) => [1, 2, 5, 10, 15].map((q) => q / fps).concat([1, 2, 5, 10, 15, 30, 60]);

/** O passo da régua (s), quantas marcas cabem entre dois números e quantos números há. */
export function rulerScale(pxPerSecond: number, duration: number, fps = 30) {
  const step = stepsFor(fps).find((p) => p * pxPerSecond >= LABEL_SPACE) ?? 60;
  const frames = Math.round(step * fps);
  // Marcas pequenas com pelo menos 6 px entre si: cada quadro quando cabe, senão menos.
  const divisions = step < 1
    ? [frames, 5, 3, 2, 1].find((d) => frames % d === 0 && (step * pxPerSecond) / d >= 6) ?? 1
    : [10, 5, 2, 1].find((d) => (step * pxPerSecond) / d >= 8) ?? 1;
  return { step, divisions, count: Math.ceil(duration / step) + 1 };
}

/** "3s" nos segundos inteiros; "15f" (o quadro dentro do segundo) no resto. */
export function rulerLabel(t: number, fps = 30) {
  const q = Math.round(t * fps);
  const s = Math.floor(q / fps), f = q % fps;
  if (f) return <span className="mt-ruler-frame">{f}f</span>;
  return s >= 60 ? `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}` : `${s}s`;
}

/** mm:ss:ff. */
export function timecode(t: number, fps = 30) {
  const m = Math.floor(t / 60), s = Math.floor(t % 60), q = Math.floor((t % 1) * fps);
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}:${String(q).padStart(2, "0")}`;
}

/** Segundos com vírgula e sinal: "+0,42s". */
export const formatSeconds = (d: number, signed = false) =>
  `${signed ? (d > 0.0005 ? "+" : d < -0.0005 ? "−" : "±") : ""}${Math.abs(d).toFixed(2).replace(".", ",")}s`;

/** O ponto mais perto dentro de `limit` (s), ou null. */
export function snapTo(t: number, points: number[], limit: number) {
  let best: number | null = null;
  for (const p of points) if (Math.abs(p - t) <= limit && (best === null || Math.abs(p - t) < Math.abs(best - t))) best = p;
  return best;
}

import * as React from "react";

// O tempo do play fora do estado de quem usa a timeline. Com o tempo num `useState`, cada quadro
// do play re-renderizava a tela inteira (99 commits/s); assim, só as folhas que mostram o tempo
// (agulha, timecode) assinam o relógio e redesenham.

export interface Clock {
  get: () => number;
  set: (t: number) => void;
  subscribe: (f: () => void) => () => void;
}

export function createClock(initial = 0): Clock {
  let t = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => t,
    set: (v) => {
      if (v === t) return;
      t = v;
      listeners.forEach((f) => f());
    },
    subscribe: (f) => {
      listeners.add(f);
      return () => {
        listeners.delete(f);
      };
    },
  };
}

/** O tempo atual do relógio, re-renderizando só quem chama. */
export const useClockTime = (c: Clock) => React.useSyncExternalStore(c.subscribe, c.get);

/** Renderiza `children(tempo)` com o tempo vivo: o pai não re-renderiza a cada quadro. */
export function WithTime({ clock, children }: { clock: Clock; children: (t: number) => React.ReactNode }) {
  return <>{children(useClockTime(clock))}</>;
}

// Tira de quadros (filmstrip) dentro de um clipe de vídeo. Recebe uma imagem com N quadros lado a
// lado (sprite) e mostra, em cada ladrilho, o quadro do tempo que cai embaixo dele, no zoom que
// estiver. Não sabe de onde vem a imagem: url e medida chegam por props.

export interface FilmstripSprite {
  /** Quadros na imagem, lado a lado. */
  frames: number;
  /** Largura e altura de um quadro na imagem (px). */
  width: number;
  height: number;
  /** Duração do vídeo que a imagem cobre (s). */
  duration: number;
}

/** Ladrilhos colados na largura natural do quadro; acima de 800 por clipe, eles se espaçam. */
const MAX_TILES = 800;

export function Filmstrip({ src, sprite, from, duration, pxPerSecond, height }: {
  src: string; sprite: FilmstripSprite;
  /** Onde o clipe começa dentro do vídeo (s) e quanto dura. */
  from: number; duration: number;
  pxPerSecond: number; height: number;
}) {
  const width = duration * pxPerSecond;
  const natural = sprite.width * (height / sprite.height);
  const tile = Math.max(natural, width / MAX_TILES);
  const count = Math.max(1, Math.ceil(width / tile));
  const tiles = [];
  for (let k = 0; k < count; k++) {
    const t = from + (k * tile + tile / 2) / pxPerSecond;
    const i = Math.max(0, Math.min(sprite.frames - 1, Math.floor((t / sprite.duration) * sprite.frames)));
    tiles.push(
      <span key={k} style={{ left: k * tile, width: natural, backgroundImage: `url(${src})`, backgroundSize: `${sprite.frames * natural}px ${height}px`, backgroundPosition: `${-i * natural}px 0` }} />,
    );
  }
  return <span aria-hidden className="mt-filmstrip">{tiles}</span>;
}

